    // Literals
    if (t.type === 'NUMBER' || t.type === 'STRING' ||
        t.type === 'BOOL'   || t.type === 'NULL'   || t.type === 'UNDEFINED') {
      consume();
      return t.value;
    }

    // Parenthesised expression
    if (t.type === 'LPAREN') {
      consume();
      const val = parseExpr();
      expect('RPAREN');
      return val;
    }

    // Identifier — resolve against ctx, then allow chained .prop and [expr]
    if (t.type === 'IDENT') {
      consume();
      let val = safeGet(ctx, t.value);

      while (peek()?.type === 'DOT' || peek()?.type === 'LBRACKET') {
        if (peek().type === 'DOT') {
          consume(); // consume '.'
          const prop = expect('IDENT').value;
          val = safeGet(val, prop);
        } else {
          consume(); // consume '['
          const key = parseExpr();
          expect('RBRACKET');
          val = safeGet(val, key);
        }
      }

      return val;
    }

    throw new SyntaxError(`Unexpected token: ${t.value}`);
  }

  const result = parseExpr();

  if (pos < tokens.length) {
    throw new SyntaxError(`Unexpected token after expression: ${tokens[pos].value}`);
  }

  return result;
}

/**
 * Public entry-point: evaluate a rule expression string against a context object.
 * Returns a boolean, or throws SyntaxError / EvalError on bad input.
 */
function evalRule(ruleExpr, context) {
  if (typeof ruleExpr !== 'string' || ruleExpr.trim() === '') {
    throw new TypeError('"rule" must be a non-empty string');
  }
  const tokens = tokenise(ruleExpr);
  const raw = evaluate(tokens, context ?? {});
  return Boolean(raw);
}

// ---------------------------------------------------------------------------
// HTTP server
// ---------------------------------------------------------------------------

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => { data += chunk; });
    req.on('end', () => resolve(data));
    req.on('error', reject);
  });
}

function send(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

const server = http.createServer(async (req, res) => {
  // ── POST /check ──────────────────────────────────────────────────────────
  if (req.method === 'POST' && req.url === '/check') {
    let parsed;
    try {
      const raw = await readBody(req);
      parsed = JSON.parse(raw);
    } catch {
      return send(res, 400, { error: 'Invalid JSON body' });
    }

    const { rule, context } = parsed;

    if (typeof rule !== 'string' || rule.trim() === '') {
      return send(res, 400, { error: '"rule" is required and must be a non-empty string' });
    }

    if (context !== undefined && (typeof context !== 'object' || Array.isArray(context) || context === null)) {
      return send(res, 400, { error: '"context" must be a plain object when provided' });
    }

    let result;
    try {
      result = evalRule(rule, context);
    } catch (err) {
      if (err instanceof SyntaxError || err instanceof TypeError || err instanceof EvalError) {
        return send(res, 422, { error: `Rule evaluation error: ${err.message}` });
      }
      throw err; // unexpected — let the outer handler deal with it
    }

    return send(res, 200, { result });
  }

  // ── 404 for everything else ───────────────────────────────────────────────
  send(res, 404, { error: 'Not found' });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = { server, evalRule }; // export for testing

'use strict';

/**
 * Tests for POST /check and the evalRule engine.
 * Run with:  node test.js
 */

const { evalRule, server } = require('./app');
const http = require('http');

let passed = 0;
let failed = 0;

function assert(label, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (ok) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}`);
    console.error(`       expected: ${JSON.stringify(expected)}`);
    console.error(`       actual  : ${JSON.stringify(actual)}`);
    failed++;
  }
}

function assertThrows(label, fn, msgIncludes) {
  try {
    fn();
    console.error(`  ✗  ${label}  (expected throw, got none)`);
    failed++;
  } catch (err) {
    if (msgIncludes && !err.message.includes(msgIncludes)) {
      console.error(`  ✗  ${label}  (wrong message: ${err.message})`);
      failed++;
    } else {
      console.log(`  ✓  ${label}`);
      passed++;
    }
  }
}

// ---------------------------------------------------------------------------
// Unit tests — evalRule()
// ---------------------------------------------------------------------------
console.log('\n── evalRule unit tests ──────────────────────────────────────────');

// Numeric comparisons
assert('amount > 100 (true)',  evalRule('amount > 100',  { amount: 150 }), true);
assert('amount > 100 (false)', evalRule('amount > 100',  { amount: 50  }), false);
assert('amount >= 100',        evalRule('amount >= 100', { amount: 100 }), true);
assert('amount <= 99',         evalRule('amount <= 99',  { amount: 99  }), true);
assert('amount < 99',          evalRule('amount < 99',   { amount: 98  }), true);
assert('amount == 42',         evalRule('amount == 42',  { amount: 42  }), true);
assert('amount != 42',         evalRule('amount != 42',  { amount: 99  }), true);

// Arithmetic
assert('amount + 10 > 15',   evalRule('amount + 10 > 15', { amount: 10 }),  true);
assert('amount * 2 == 20',   evalRule('amount * 2 == 20', { amount: 10 }),  true);
assert('amount - 5 < 10',    evalRule('amount - 5 < 10',  { amount: 14 }),  true);
assert('amount / 2 == 5',    evalRule('amount / 2 == 5',  { amount: 10 }),  true);
assert('amount % 3 == 1',    evalRule('amount % 3 == 1',  { amount: 7  }),  true);

// Boolean logic
assert('&&  both true',      evalRule('a > 0 && b > 0',     { a: 1, b: 2 }), true);
assert('&&  one false',      evalRule('a > 0 && b > 10',    { a: 1, b: 2 }), false);
assert('||  one true',       evalRule('a > 10 || b > 1',    { a: 1, b: 2 }), true);
assert('||  both false',     evalRule('a > 10 || b > 10',   { a: 1, b: 2 }), false);
assert('!   negation true',  evalRule('!(a > 10)',           { a: 1 }),        true);
assert('!   negation false', evalRule('!(a > 0)',            { a: 1 }),        false);

// String comparison
assert('status == "active"',  evalRule('status == "active"', { status: 'active' }),   true);
assert('status == "active" (false)', evalRule('status == "active"', { status: 'inactive' }), false);
assert("single-quote string", evalRule("status == 'vip'",    { status: 'vip' }),      true);

// Nested property access
assert('user.age > 18',       evalRule('user.age > 18', { user: { age: 21 } }),        true);
assert('user.role == "admin"',evalRule('user.role == "admin"', { user: { role: 'admin' } }), true);

// Bracket access
assert('arr[0] == 5',         evalRule('arr[0] == 5', { arr: [5, 6, 7] }),             true);
assert('map["key"] == 1',     evalRule('map["key"] == 1', { map: { key: 1 } }),        true);

// Literals
assert('true literal',        evalRule('true',  {}),  true);
assert('false literal',       evalRule('false', {}),  false);
assert('null literal',        evalRule('val == null', { val: null }), true);

// Parentheses / precedence
assert('(a + b) * 2 == 6',   evalRule('(a + b) * 2 == 6', { a: 1, b: 2 }), true);

// Unary minus
assert('-amount < 0',         evalRule('-amount < 0', { amount: 5 }), true);

// Empty / missing context keys resolve to undefined (falsy)
assert('missing key is undefined', evalRule('x == undefined', {}), true);

// ---------------------------------------------------------------------------
// Security — prototype pollution attempts must throw
// ---------------------------------------------------------------------------
console.log('\n── Security tests ───────────────────────────────────────────────');

assertThrows(
  '__proto__ access blocked',
  () => evalRule('__proto__.polluted == true', {}),
  'not allowed'
);
assertThrows(
  'constructor access blocked',
  () => evalRule('constructor.name', {}),
  'not allowed'
);
assertThrows(
  'prototype access blocked',
  () => evalRule('foo.prototype.bar', { foo: {} }),
  'not allowed'
);

// ---------------------------------------------------------------------------
// Input validation errors
// ---------------------------------------------------------------------------
console.log('\n── Input validation (evalRule errors) ───────────────────────────');

assertThrows('empty rule throws',      () => evalRule('',    {}),  'non-empty');
assertThrows('non-string rule throws', () => evalRule(null,  {}),  'non-empty');
assertThrows('unterminated string',    () => evalRule('"abc', {}), 'Unterminated');
assertThrows('unexpected char',        () => evalRule('a @ b', {}), 'Unexpected character');
assertThrows('trailing garbage',       () => evalRule('1 + 2 )', {}), 'Unexpected token after');

// ---------------------------------------------------------------------------
// HTTP integration tests — POST /check
// ---------------------------------------------------------------------------
console.log('\n── HTTP integration tests ───────────────────────────────────────');

const PORT = 3099;

function postCheck(body) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    const req = http.request(
      { hostname: '127.0.0.1', port: PORT, path: '/check', method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } },
      res => {
        let data = '';
        res.on('data', c => { data += c; });
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(data) }));
      }
    );
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

async function runHttpTests() {
  const testServer = server;
  await new Promise(r => testServer.listen(PORT, r));

  try {
    let r;

    // 200 — simple true
    r = await postCheck({ rule: 'amount > 100', context: { amount: 200 } });
    assert('HTTP 200 result=true',  r.status, 200);
    assert('HTTP body.result=true', r.body.result, true);

    // 200 — simple false
    r = await postCheck({ rule: 'amount > 100', context: { amount: 50 } });
    assert('HTTP 200 result=false',  r.status, 200);
    assert('HTTP body.result=false', r.body.result, false);

    // 200 — nested property
    r = await postCheck({ rule: 'user.score >= 90', context: { user: { score: 95 } } });
    assert('HTTP 200 nested prop', r.body.result, true);

    // 200 — no context key (undefined)
    r = await postCheck({ rule: 'x == undefined', context: {} });
    assert('HTTP 200 undefined ctx key', r.body.result, true);

    // 200 — context omitted entirely (defaults to {})
    r = await postCheck({ rule: 'true' });
    assert('HTTP 200 no context', r.status, 200);
    assert('HTTP body.result literal true', r.body.result, true);

    // 400 — missing rule
    r = await postCheck({ context: { a: 1 } });
    assert('HTTP 400 missing rule', r.status, 400);

    // 400 — empty rule
    r = await postCheck({ rule: '', context: {} });
    assert('HTTP 400 empty rule', r.status, 400);

    // 400 — invalid JSON  (send raw)
    const badJson = await new Promise((resolve, reject) => {
      const payload = 'not-json';
      const req = http.request(
        { hostname: '127.0.0.1', port: PORT, path: '/check', method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } },
        res => {
          let data = '';
          res.on('data', c => { data += c; });
          res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(data) }));
        }
      );
      req.on('error', reject);
      req.write(payload);
      req.end();
    });
    assert('HTTP 400 invalid JSON', badJson.status, 400);

    // 400 — context is an array (not a plain object)
    r = await postCheck({ rule: 'true', context: [1, 2] });
    assert('HTTP 400 context is array', r.status, 400);

    // 422 — bad rule syntax
    r = await postCheck({ rule: 'amount @@@ 5', context: { amount: 1 } });
    assert('HTTP 422 bad rule syntax', r.status, 422);

    // 422 — prototype pollution via HTTP
    r = await postCheck({ rule: '__proto__.x == 1', context: {} });
    assert('HTTP 422 prototype pollution blocked', r.status, 422);

    // 404 — wrong path
    const notFound = await new Promise((resolve, reject) => {
      const req = http.request(
        { hostname: '127.0.0.1', port: PORT, path: '/other', method: 'GET' },
        res => {
          let data = '';
          res.on('data', c => { data += c; });
          res.on('end', () => resolve({ status: res.statusCode }));
        }
      );
      req.on('error', reject);
      req.end();
    });
    assert('HTTP 404 wrong path', notFound.status, 404);

  } finally {
    await new Promise(r => testServer.close(r));
  }
}

runHttpTests().then(() => {
  console.log(`\n────────────────────────────────────────────────────────────────`);
  console.log(`Results: ${passed} passed, ${failed} failed`);
  if (failed > 0) process.exit(1);
}).catch(err => {
  console.error('Unexpected test error:', err);
  process.exit(1);
});

