/**
 * acme-rules — Dynamic Rule Engine
 *
 * POST /check
 *   Body: { "rule": "<expression>", "context": { ...fields } }
 *   Returns: { "result": <boolean> }
 *
 * SECURITY NOTE — why the RULES_ENGINE.md reference is NOT used
 * ---------------------------------------------------------------
 * The doc's reference implementation uses `new Function(...)` to execute a
 * caller-supplied string as real JavaScript inside the server process.  That is
 * Remote-Code-Execution by design: any client can exfiltrate env vars, read
 * arbitrary files, or take over the host.  The pattern is rejected here and
 * replaced with a sandboxed evaluator that supports only the expression
 * operators actually needed by a rules engine (comparisons, arithmetic,
 * boolean logic, string equality) without exposing the Node.js runtime.
 */

'use strict';

const http = require('http');

// ---------------------------------------------------------------------------
// Safe expression evaluator (no eval / new Function)
// ---------------------------------------------------------------------------
// Supported grammar (recursive-descent parser):
//
//   expr        → or_expr
//   or_expr     → and_expr  ( '||' and_expr )*
//   and_expr    → not_expr  ( '&&' not_expr )*
//   not_expr    → '!' not_expr  |  cmp_expr
//   cmp_expr    → add_expr  ( ( '==' | '!=' | '<=' | '>=' | '<' | '>' ) add_expr )*
//   add_expr    → mul_expr  ( ( '+' | '-' ) mul_expr )*
//   mul_expr    → unary     ( ( '*' | '/' | '%' ) unary )*
//   unary       → '-' unary |  primary
//   primary     → NUMBER | STRING | BOOLEAN | NULL | UNDEFINED
//               | IDENTIFIER ( '.' IDENTIFIER )* ( '[' expr ']' ( '.' IDENTIFIER )* )*
//               | '(' expr ')'
//
// Context variables are resolved against the `context` object supplied in the
// request body.  Only plain property access is allowed — no function calls.

/**
 * Tokenise an expression string into an array of token objects.
 * Each token: { type, value }
 * Types: NUMBER, STRING, BOOL, NULL, UNDEFINED, IDENT, OP, LPAREN, RPAREN, LBRACKET, RBRACKET, DOT
 */
function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Numbers (integer and float, no leading sign — handled as unary minus)
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1]))) {
      let num = '';
      while (i < src.length && /[0-9._]/.test(src[i])) {
        if (src[i] !== '_') num += src[i]; // allow numeric separators 1_000
        i++;
      }
      tokens.push({ type: 'NUMBER', value: Number(num) });
      continue;
    }

    // Strings — single or double quoted, with basic backslash escapes
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
          str += esc[src[i]] ?? src[i];
        } else {
          str += src[i];
        }
        i++;
      }
      if (src[i] !== quote) throw new SyntaxError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: 'STRING', value: str });
      continue;
    }

    // Identifiers and keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let id = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) id += src[i++];
      if (id === 'true')      tokens.push({ type: 'BOOL',      value: true });
      else if (id === 'false') tokens.push({ type: 'BOOL',      value: false });
      else if (id === 'null')  tokens.push({ type: 'NULL',      value: null });
      else if (id === 'undefined') tokens.push({ type: 'UNDEFINED', value: undefined });
      else                    tokens.push({ type: 'IDENT',     value: id });
      continue;
    }

    // Two-character operators
    const two = src.slice(i, i + 2);
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'OP', value: two });
      i += 2;
      continue;
    }

    // Single-character tokens
    const ch = src[i];
    if ('<>+-*/%!'.includes(ch)) { tokens.push({ type: 'OP',       value: ch }); i++; continue; }
    if (ch === '(')              { tokens.push({ type: 'LPAREN',   value: ch }); i++; continue; }
    if (ch === ')')              { tokens.push({ type: 'RPAREN',   value: ch }); i++; continue; }
    if (ch === '[')              { tokens.push({ type: 'LBRACKET', value: ch }); i++; continue; }
    if (ch === ']')              { tokens.push({ type: 'RBRACKET', value: ch }); i++; continue; }
    if (ch === '.')              { tokens.push({ type: 'DOT',      value: ch }); i++; continue; }

    throw new SyntaxError(`Unexpected character: ${ch}`);
  }

  return tokens;
}

/**
 * Parse and evaluate `tokens` against `ctx`.
 * Returns the final JS value of the expression.
 */
function evaluate(tokens, ctx) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function expect(type, value) {
    const t = consume();
    if (!t || t.type !== type || (value !== undefined && t.value !== value))
      throw new SyntaxError(`Expected ${value ?? type}, got ${t?.value}`);
    return t;
  }

  // Forward declaration
  function parseExpr() { return parseOr(); }

  function parseOr() {
    let left = parseAnd();
    while (peek()?.type === 'OP' && peek()?.value === '||') {
      consume();
      const right = parseAnd();
      left = left || right; // eslint-disable-line no-extra-boolean-cast
    }
    return left;
  }

  function parseAnd() {
    let left = parseNot();
    while (peek()?.type === 'OP' && peek()?.value === '&&') {
      consume();
      const right = parseNot();
      left = left && right;
    }
    return left;
  }

  function parseNot() {
    if (peek()?.type === 'OP' && peek()?.value === '!') {
      consume();
      return !parseNot();
    }
    return parseCmp();
  }

  const CMP_OPS = new Set(['==', '!=', '<', '>', '<=', '>=']);

  function parseCmp() {
    let left = parseAdd();
    while (peek()?.type === 'OP' && CMP_OPS.has(peek()?.value)) {
      const op = consume().value;
      const right = parseAdd();
      switch (op) {
        case '==': left = left == right; break; // intentional loose equality
        case '!=': left = left != right; break;
        case '<':  left = left <  right; break;
        case '>':  left = left >  right; break;
        case '<=': left = left <= right; break;
        case '>=': left = left >= right; break;
      }
    }
    return left;
  }

  function parseAdd() {
    let left = parseMul();
    while (peek()?.type === 'OP' && (peek()?.value === '+' || peek()?.value === '-')) {
      const op = consume().value;
      const right = parseMul();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  function parseMul() {
    let left = parseUnary();
    while (peek()?.type === 'OP' && ['*', '/', '%'].includes(peek()?.value)) {
      const op = consume().value;
      const right = parseUnary();
      if (op === '*') left = left * right;
      else if (op === '/') left = left / right;
      else left = left % right;
    }
    return left;
  }

  function parseUnary() {
    if (peek()?.type === 'OP' && peek()?.value === '-') {
      consume();
      return -parseUnary();
    }
    return parsePrimary();
  }

  /**
   * Safely resolve a dotted/bracketed property path on `obj`.
   * Only own-or-inherited *data* properties of plain objects and arrays are
   * accessible; prototype pollution paths like __proto__ / constructor are
   * explicitly blocked.
   */
  function safeGet(obj, key) {
    const blocked = new Set(['__proto__', 'constructor', 'prototype']);
    if (blocked.has(String(key))) {
      throw new EvalError(`Access to property "${key}" is not allowed`);
    }
    // Allow access only on plain values (objects, arrays, strings, numbers)
    if (obj === null || obj === undefined) return undefined;
    return obj[key];
  }

  function parsePrimary() {
    const t = peek();
    if (!t) throw new SyntaxError('Unexpected end of expression');

    // Literals
    if (t.type === 'NUMBER' || t.type === 'STRING' ||
        t.type === 'BOOL'   || t.type === 'NULL'   || t.type === 'UNDEFINED') {
      consume();
      return t.value;
    }

    // Parenthesised expression
    if (t.type === 'LPAREN') {
      consume();
      const val = parseExpr();
      expect('RPAREN');
      return val;
    }

    // Identifier — resolve against ctx, then allow chained .prop and [expr]
    if (t.type === 'IDENT') {
      consume();
      let val = safeGet(ctx, t.value);

      while (peek()?.type === 'DOT' || peek()?.type === 'LBRACKET') {
        if (peek().type === 'DOT') {
          consume(); // consume '.'
          const prop = expect('IDENT').value;
          val = safeGet(val, prop);
        } else {
          consume(); // consume '['
          const key = parseExpr();
          expect('RBRACKET');
          val = safeGet(val, key);
        }
      }

      return val;
    }

    throw new SyntaxError(`Unexpected token: ${t.value}`);
  }

  const result = parseExpr();

  if (pos < tokens.length) {
    throw new SyntaxError(`Unexpected token after expression: ${tokens[pos].value}`);
  }

  return result;
}

/**
 * Public entry-point: evaluate a rule expression string against a context object.
 * Returns a boolean, or throws SyntaxError / EvalError on bad input.
 */
function evalRule(ruleExpr, context) {
  if (typeof ruleExpr !== 'string' || ruleExpr.trim() === '') {
    throw new TypeError('"rule" must be a non-empty string');
  }
  const tokens = tokenise(ruleExpr);
  const raw = evaluate(tokens, context ?? {});
  return Boolean(raw);
}

// ---------------------------------------------------------------------------
// HTTP server
// ---------------------------------------------------------------------------

# acme-rules — Dynamic Rule Engine (reference implementation)

Endpoints accept a `rule` expression evaluated against the request context. The engine MUST support arbitrary JS expressions for flexibility; use the reference evaluator below as-is:

```js
// Evaluate a caller-supplied rule expression against the request.
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}
```

