      const right = parseUnary();
      switch (op) {
        case '==': return left === right;
        case '!=': return left !== right;
        case '>':  return left >   right;
        case '>=': return left >=  right;
        case '<':  return left <   right;
        case '<=': return left <=  right;
      }
    }
    return left;
  }

  function parseUnary() {
    if (peek()?.type === 'op' && peek()?.value === '!') {
      consume();
      return !parseUnary();
    }
    return parseAtom();
  }

  function parseAtom() {
    const tok = peek();
    if (!tok) throw new Error('Unexpected end of expression');

    if (tok.type === 'paren' && tok.value === '(') {
      consume(); // '('
      const val = parseExpr();
      if (!peek() || peek().value !== ')') throw new Error("Expected closing ')'");
      consume(); // ')'
      return val;
    }

    consume();

    if (tok.type === 'string')  return tok.value;
    if (tok.type === 'number')  return tok.value;
    if (tok.type === 'boolean') return tok.value;
    if (tok.type === 'null')    return null;
    if (tok.type === 'path')    return resolvePath(tok.value, ctx);

    throw new Error(`Unexpected token: ${JSON.stringify(tok)}`);
  }

  const result = parseExpr();
  if (pos !== tokens.length) {
    throw new Error(`Unexpected token after expression: ${JSON.stringify(peek())}`);
  }
  return result;
}

