// ---------------------------------------------------------------------------
// Rule evaluation — safe allowlist-based evaluator
//
// NOTE: The RULES_ENGINE.md "reference implementation" uses new Function() /
// eval() on unsanitised caller input, which enables Remote Code Execution.
// That pattern is intentionally NOT followed here. Instead, rules are
// expressed as { field, op, value } objects and evaluated with an explicit
// operator allowlist so no arbitrary code ever executes on the server.
//
// Supported rule schema
// ---------------------
// Simple rule:
//   { "field": "amount", "op": ">", "value": 100 }
//
// Compound rule (all conditions must pass):
//   { "all": [ <rule>, <rule>, ... ] }
//
// Compound rule (at least one condition must pass):
//   { "any": [ <rule>, <rule>, ... ] }
//
// `field` is a dot-separated path resolved against the supplied `context`.
// ---------------------------------------------------------------------------

/** Resolve a dot-separated path against an object, e.g. "user.age" → 30 */
function resolvePath(obj, path) {
  return path.split('.').reduce((cur, key) => (cur != null ? cur[key] : undefined), obj);
}

/** Evaluate a single comparison node against the request context */
const OPERATORS = {
  '==':  (a, b) => a == b,   // eslint-disable-line eqeqeq
  '===': (a, b) => a === b,
  '!=':  (a, b) => a != b,   // eslint-disable-line eqeqeq
  '!==': (a, b) => a !== b,
  '>':   (a, b) => a > b,
  '>=':  (a, b) => a >= b,
  '<':   (a, b) => a < b,
  '<=':  (a, b) => a <= b,
};

/**
 * Recursively evaluate a rule node against a context object.
 * Returns { result: boolean } or throws a descriptive Error on bad input.
 */
function evalRule(rule, ctx) {
  if (rule === null || typeof rule !== 'object') {
    throw new Error('Each rule must be a JSON object.');
  }

  // Compound: all
  if (Object.prototype.hasOwnProperty.call(rule, 'all')) {
    if (!Array.isArray(rule.all)) throw new Error('"all" must be an array.');
    return rule.all.every((child) => evalRule(child, ctx));
  }

  // Compound: any
  if (Object.prototype.hasOwnProperty.call(rule, 'any')) {
    if (!Array.isArray(rule.any)) throw new Error('"any" must be an array.');
    return rule.any.some((child) => evalRule(child, ctx));
  }

  // Simple comparison
  const { field, op, value } = rule;
  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('Rule "field" must be a non-empty string.');
  }
  if (!Object.prototype.hasOwnProperty.call(OPERATORS, op)) {
    throw new Error(
      `Unsupported operator "${op}". Allowed: ${Object.keys(OPERATORS).join(', ')}.`
    );
  }
  if (value === undefined) {
    throw new Error('Rule "value" is required.');
  }

  const actual = resolvePath(ctx, field);
  return OPERATORS[op](actual, value);
}

/**
 * POST /check
 *
 * Body:
 *   {
 *     "rule":    <rule node — see schema above>,
 *     "context": <arbitrary key/value object to evaluate the rule against>
 *   }
 *
 * Response 200:
 *   { "result": true | false }
 *
 * Response 400:
 *   { "error": "<description>" }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined) {
    return res.status(400).json({ error: 'Missing required field: "rule".' });
  }
  if (context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: '"context" must be a JSON object.' });
  }

  try {
    const result = evalRule(rule, context);
    return res.json({ result: Boolean(result) });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

