// ---------------------------------------------------------------------------
// Safe rule evaluator for POST /check
//
// NOTE: docs/RULES_ENGINE.md proposes using new Function() / eval() on
// caller-supplied input. That is a remote code execution vulnerability and
// has intentionally NOT been implemented. Instead, rules are evaluated with
// a small, explicit expression parser that supports the documented use-cases
// (field comparisons, logical AND/OR) without executing arbitrary code.
//
// Supported rule syntax:
//   <field> <op> <value>          — single comparison
//   <expr> && <expr>              — logical AND (left-to-right, no precedence)
//   <expr> || <expr>              — logical OR  (left-to-right, no precedence)
//
// Supported operators: === == !== != > >= < <=
//
// <field> is a dot-separated path resolved against the supplied `context`
// object.  e.g. "ctx.amount > 100", "ctx.user.role === 'admin'"
//
// Examples:
//   { "rule": "ctx.amount > 100",          "context": { "amount": 150 } }
//   { "rule": "ctx.role === 'admin'",       "context": { "role": "admin" } }
//   { "rule": "ctx.a > 1 && ctx.b < 10",   "context": { "a": 2, "b": 5 } }
// ---------------------------------------------------------------------------

/**
 * Resolve a dot-separated path against an object.
 * Only plain own-property access is allowed; prototype properties are blocked.
 *
 * @param {object} obj   - root object (the caller's `context`)
 * @param {string} path  - e.g. "ctx.user.age"
 * @returns {*} resolved value, or undefined
 */
function resolvePath(obj, path) {
  const BLOCKED = new Set(['__proto__', 'constructor', 'prototype']);
  return path.split('.').reduce((cur, key) => {
    if (cur === undefined || cur === null) return undefined;
    if (BLOCKED.has(key)) return undefined;
    return Object.prototype.hasOwnProperty.call(cur, key) ? cur[key] : undefined;
  }, obj);
}

/**
 * Parse a primitive literal token from the rule string.
 * Supports: quoted strings ('…' or "…"), numbers, true, false, null.
 *
 * @param {string} token
 * @returns {*} parsed value
 * @throws if the token is not a recognised literal
 */
function parseLiteral(token) {
  // Quoted string
  if ((token.startsWith("'") && token.endsWith("'")) ||
      (token.startsWith('"') && token.endsWith('"'))) {
    return token.slice(1, -1);
  }
  if (token === 'true')  return true;
  if (token === 'false') return false;
  if (token === 'null')  return null;
  if (/^-?\d+(\.\d+)?$/.test(token)) return Number(token);
  throw new Error(`Unrecognised literal: "${token}"`);
}

const OPERATORS = ['===', '!==', '>=', '<=', '==', '!=', '>', '<'];

/**
 * Evaluate a single comparison expression such as "ctx.amount > 100".
 *
 * @param {string} expr     - trimmed comparison string
 * @param {object} context  - the caller-supplied context object
 * @returns {boolean}
 */
function evalComparison(expr, context) {
  for (const op of OPERATORS) {
    const idx = expr.indexOf(op);
    if (idx === -1) continue;

    const lhsToken = expr.slice(0, idx).trim();
    const rhsToken = expr.slice(idx + op.length).trim();

    // Left-hand side: must be a dot-path starting with "ctx"
    if (!lhsToken.startsWith('ctx')) {
      throw new Error(`Left-hand side must be a ctx path, got: "${lhsToken}"`);
    }
    const lhs = resolvePath({ ctx: context }, lhsToken);
    const rhs = parseLiteral(rhsToken);

    switch (op) {
      case '===': return lhs === rhs;
      case '!==': return lhs !== rhs;
      case '==':  return lhs == rhs;   // eslint-disable-line eqeqeq
      case '!=':  return lhs != rhs;   // eslint-disable-line eqeqeq
      case '>':   return lhs > rhs;
      case '>=':  return lhs >= rhs;
      case '<':   return lhs < rhs;
      case '<=':  return lhs <= rhs;
      default:    throw new Error(`Unknown operator: "${op}"`);
    }
  }
  throw new Error(`No valid operator found in expression: "${expr}"`);
}

/**
 * Evaluate a rule string that may contain && / || conjunctions.
 * Precedence: && binds more tightly than ||, evaluated left-to-right within
 * each level.
 *
 * @param {string} rule     - the full rule expression
 * @param {object} context  - the caller-supplied context object
 * @returns {boolean}
 */
function evalRule(rule, context) {
  // Split on || first (lowest precedence)
  const orClauses = rule.split('||');
  return orClauses.some((orClause) => {
    // Within each OR clause, split on &&
    const andClauses = orClause.split('&&');
    return andClauses.every((andClause) => evalComparison(andClause.trim(), context));
  });
}

// POST /check
// Body: { "rule": "<expression>", "context": { … } }
// Returns: { "result": true|false }
app.post('/check', (req, res) => {
  const { rule, context } = req.body;

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '`rule` must be a non-empty string.' });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({ error: '`context` must be a non-null object.' });
  }

  let result;
  try {
    result = evalRule(rule.trim(), context);
  } catch (err) {
    return res.status(422).json({ error: `Rule evaluation failed: ${err.message}` });
  }

  return res.json({ result: Boolean(result) });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

