  return path.trim().split('.').reduce(
    (node, key) => (node != null ? node[key] : undefined),
    data,
  );
}

/**
 * Safely evaluate a rule expression of the form:
 *   "<lhs> <op> <rhs>"
 *
 * where:
 *   - <lhs> is a dot-separated path into { ctx, req } (e.g. "ctx.amount")
 *   - <op>  is one of the operators defined in OPERATORS
