 * proper 400 rather than a 500.
 */
function evalRule(rule, ctx, req) {
  // Sort operators longest-first so multi-char ops (e.g. !==) match before
  // their shorter prefixes (e.g. !=).
  const sortedOps = Object.keys(OPERATORS).sort((a, b) => b.length - a.length);

  // Escape each operator string for safe use inside a RegExp character class.
  const escapedOps = sortedOps.map(op =>
    op.split('').map(ch => ('^$.|?*+()[]{}'.includes(ch) ? '\\' + ch : ch)).join(''),
  );

  const opPattern = escapedOps.join('|');
  const ruleRegex = new RegExp(`^\\s*(\\S+)\\s+(${opPattern})\\s+(\\S.*?)\\s*$`);
