const app = require('./app.js');        // spins up the server; we only need the logic
// Re-require the functions by extracting them from the module cache source,
// but it's easier to just test via HTTP now the server is up.

const http = require('http');

function post(body) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(body);
    const req = http.request(
      { hostname: 'localhost', port: 3000, path: '/check', method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } },
      (res) => {
        let buf = '';
        res.on('data', c => buf += c);
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(buf) }));
      },
    );
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function run() {
  const tests = [
    // ── happy-path numeric comparisons ──────────────────────────────────────
    { desc: 'amount > 100  (true)',  body: { rule: 'ctx.amount > 100',  context: { amount: 150  } }, wantResult: true,  wantStatus: 200 },
    { desc: 'amount > 100  (false)', body: { rule: 'ctx.amount > 100',  context: { amount: 50   } }, wantResult: false, wantStatus: 200 },
    { desc: 'score >= 0.5  (true)',  body: { rule: 'ctx.score >= 0.5',  context: { score: 0.5   } }, wantResult: true,  wantStatus: 200 },
    { desc: 'score < 1     (true)',  body: { rule: 'ctx.score < 1',     context: { score: 0.9   } }, wantResult: true,  wantStatus: 200 },
    // ── equality / inequality ────────────────────────────────────────────────
    { desc: 'role === admin (true)', body: { rule: 'ctx.role === "admin"', context: { role: 'admin' } }, wantResult: true,  wantStatus: 200 },
    { desc: 'role === admin (false)',body: { rule: 'ctx.role === "admin"', context: { role: 'user'  } }, wantResult: false, wantStatus: 200 },
    { desc: 'flag !== true  (true)', body: { rule: 'ctx.flag !== true',   context: { flag: false  } }, wantResult: true,  wantStatus: 200 },
    // ── nested path ─────────────────────────────────────────────────────────
    { desc: 'nested user.age > 17', body: { rule: 'ctx.user.age > 17', context: { user: { age: 18 } } }, wantResult: true, wantStatus: 200 },
    // ── 400 cases ───────────────────────────────────────────────────────────
    { desc: 'missing rule field',    body: { context: {} },                        wantStatus: 400 },
    { desc: 'missing context field', body: { rule: 'ctx.x > 1' },                  wantStatus: 400 },
    { desc: 'unknown path',          body: { rule: 'ctx.ghost > 0', context: {} }, wantStatus: 400 },
    { desc: 'bad rhs literal',       body: { rule: 'ctx.x > foo',   context: { x: 1 } }, wantStatus: 400 },
    // ── injection attempts must NOT succeed ─────────────────────────────────
    { desc: 'injection: process.env',      body: { rule: 'ctx.x > 0',    context: { x: 'process.env' } }, wantStatus: 400 },
    { desc: 'injection: execSync payload', body: { rule: "require('child_process').execSync('id').toString() === \"\"", context: {} }, wantStatus: 400 },
  ];

  let passed = 0, failed = 0;
  for (const t of tests) {
    const { status, body } = await post(t.body);
    const statusOk = status === t.wantStatus;
    const resultOk = t.wantResult === undefined || body.result === t.wantResult;
    const ok = statusOk && resultOk;
    console.log(`${ok ? '✓' : '✗'} [${status}] ${t.desc}${ok ? '' : `  → got ${JSON.stringify(body)}`}`);
    ok ? passed++ : failed++;
  }
  console.log(`\n${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}

run().catch(e => { console.error(e); process.exit(1); });
